import{_ as s}from"./chunks/continuous_data_copy_diagram.VA_ibWhI.js";import{_ as t}from"./chunks/datacopy_address_overlap_sync_diagram.Beodm7Hh.js";import{_ as l,o as n,a as p,b as i}from"./app.DKoEZOcr.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"数据搬运","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/data_move"},{"text":"DataCopy（GM与UB连续数据搬运）","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_GMAndUB_continuous"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_GMAndUB_continuous.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_GMAndUB_continuous.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),e={name:"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_GMAndUB_continuous.md"};function c(o,a,d,r,h,_){return n(),p("div",null,[...a[0]||(a[0]=[i(`<div><article class="markdown-body"><h1>DataCopy（GM与UB连续数据搬运）<span id="ZH-CN_TOPIC_0000002382908021"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h2 id="功能说明">功能说明<span id="section474617392321"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>支持Global Memory与Unified Buffer（UB）之间的连续数据搬运，数据在传输过程中保持原始格式和内容不变。</p><p>具体支持的数据通路为（以<a href="../../aux_data_structures/TPosition.html">逻辑位置TPosition</a>表示）：</p><ul><li>Global Memory -&gt; UB <ul><li>GM -&gt; VECIN</li></ul></li><li>UB -&gt; Global Memory <ul><li>VECOUT -&gt; GM</li></ul><div data-filter="310p"><ul><li>CO2 -&gt; GM（仅Atlas 推理系列产品AI Core支持）</li></ul></div></li></ul><h2 id="函数原型">函数原型<span id="section1954364615315"></span><a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>Global Memory -&gt; UB</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">)</span>
</code></pre></div></li><li><p>UB -&gt; Global Memory</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">)</span>
</code></pre></div></li></ul><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">T</td><td align="left">操作数的数据类型。支持的数据类型请参考<a href="#section4219135304818">数据类型</a>。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="center">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">dst</td><td align="center">输出</td><td align="left">目的操作数。<br>•类型为<a href="../../data_structures/LocalTensor/LocalTensor_intro.html">LocalTensor</a>时，存储位置为UB，目的地址需要32字节对齐。<br>•类型为<a href="../../data_structures/GlobalTensor/GlobalTensor_intro.html">GlobalTensor</a>时，存储位置为Global Memory，目的地址需要按照对应数据类型所占字节数对齐。</td></tr><tr><td align="left">src</td><td align="center">输入</td><td align="left">源操作数。<br>•类型为GlobalTensor时，存储位置为Global Memory，源地址需要按照对应数据类型所占字节数对齐。<br>•类型为LocalTensor时，存储位置为UB，源地址需要32字节对齐。</td></tr><tr><td align="left">count</td><td align="center">输入</td><td align="left">参与搬运的元素个数。<br><strong>注：count * sizeof(T)需要32字节对齐，若未对齐，搬运量会向下取整到32字节对齐。</strong></td></tr></tbody></table><p>以half数据类型为例，源操作数的shape为1 * 128。当count = 128时，<a href="#zh-cn_topic_0000002534928976_fig54801848104717">图1</a>将源操作数中128个元素连续搬运至目的操作数。</p><p><strong>图1</strong> 连续搬运示意图<span id="zh-cn_topic_0000002534928976_fig54801848104717"></span><br><img src="`+s+'" alt title="连续搬运示意图"></p><h2 id="数据类型">数据类型<span id="section4219135304818"></span><a class="header-anchor" href="#数据类型">​</a></h2><p>源操作数和目的操作数支持的数据类型保持一致，Global Memory -&gt; UB和UB -&gt; Global Memory两个数据通路对同一产品支持的数据类型相同，具体如下：</p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT，支持的数据类型为：b8、b16、b32、b64。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="x90"><ul><li>Kirin X90，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><h2 id="返回值说明">返回值说明<span id="section44801012174220"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>位于Global Memory的地址必须按照对应数据类型所占字节数对齐，位于UB的地址必须32字节对齐。</p></li><li><p>调用连续搬运接口时，count * sizeof(T)需要32字节对齐，若未对齐，则搬运量会向下取整到32字节对齐。</p></li><li><p>如果需要执行多个DataCopy指令，且DataCopy的目的地址存在重叠，需要通过调用<a href="../../sync_control/intra_core_sync/PipeBarrier_ISASI.html">PipeBarrier(ISASI)</a>来插入同步指令，保证多个DataCopy指令的串行化，防止出现异常数据。如下图左侧示意图，执行两个DataCopy指令，搬运的目的Global Memory地址存在重叠，两条搬运指令之间需要通过调用<code>PipeBarrier&lt;PIPE_MTE3&gt;()</code>添加MTE3搬出流水的同步；如下图右侧示意图所示，搬运的目的地址UB存在重叠，两条搬运指令之间需要调用<code>PipeBarrier&lt;PIPE_MTE2&gt;()</code>添加MTE2搬入流水的同步。</p><p><img src="'+t+`" alt></p></li></ul><div data-filter="910b,A3"><ul><li><p>针对如下产品型号：</p><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul><p>在跨卡通信算子开发场景，DataCopy类接口支持跨卡数据搬运，仅支持HCCS物理链路，不支持其他通路；开发者开发过程中，需要关注涉及卡间通信的物理通路，可通过<code>npu-smi info -t topo</code>命令查询HCCS物理链路。</p></li></ul></div><h2 id="调用示例">调用示例<span id="section122101199486"></span><a class="header-anchor" href="#调用示例">​</a></h2><ul><li><p>Global Memory -&gt; UB</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// srcLocal为half类型的LocalTensor，srcGlobal为half类型的GlobalTensor。</span>
<span class="c1">// 使用传入count参数的搬运接口，完成连续搬运。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcGlobal</span><span class="p">,</span><span class="w"> </span><span class="mi">512</span><span class="p">);</span>
</code></pre></div><p>结果示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>输入数据srcGlobal：[1 2 3 ... 512]
输出数据srcLocal：[1 2 3 ... 512]
</code></pre></div></li><li><p>UB -&gt; Global Memory</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// dstLocal为half类型的LocalTensor，dstGlobal为half类型的GlobalTensor。</span>
<span class="c1">// 使用传入count参数的搬运接口，完成连续搬运。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="mi">512</span><span class="p">);</span>
</code></pre></div><p>结果示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>输入数据dstLocal：[1 2 3 ... 512]
输出数据dstGlobal：[1 2 3 ... 512]
</code></pre></div></li></ul></article></div>`,1)])])}const g=l(e,[["render",c]]);export{A as __pageData,g as default};
